'use client'
/** AGENT: the MATRIX card `hb-agent` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { heartbeatBoard } from '@/lib/matrix/widgets/boards/heartbeat'

const preset = heartbeatBoard.find(p => p.id === 'hb-agent')!

export type MatrixHbAgentProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixHbAgent(props: MatrixHbAgentProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
